# QM I exercise sheets I-VI (HS25 set, Gaberdiel), condensed from the official sheets and solutions.
# Style rule for these files: no ASCII apostrophes inside r'...' strings (use ’ in text, ^\prime in math).
from qm_sheet_lib import S, Q

S(1, 'Compton, Bohr, Galilei', '2025-09-24', [
 Q(1, 'Compton effect', 'wave-mechanics-basics', ['qm-wm-L1', 'qm-wm-D1', 'qm-wm-c1'],
   r'(i) Thomson: an electron at rest in the field $\vec E=\vec\varepsilon E_0\cos(kx-\omega t)$ obeys $m\ddot{\vec x}=-e\vec E$ (magnetic force neglected). Solve it; what is the frequency of the emitted light? (ii) Compton: treat light as photons, $(cp_1,\vec p_1)$, $\lambda_1=h/p_1$, scattering elastically off the electron by an angle $\theta$. Show $\lambda_2=\lambda_1+\frac{h}{mc}(1-\cos\theta)$. (iii) In which limit is Thomson scattering recovered, and for which light is the Compton effect observable?',
   [('(i) Classical motion.', r'With $\vec k\parallel\hat e_3$ the motion is transverse: $\vec x(t)=-\frac{eE_0}{m\omega^2}\vec\varepsilon(1-\cos\omega t)$. The electron oscillates at $\omega$ and radiates as a dipole at the same frequency $\omega$: no frequency shift classically.'),
    ('(ii) Four-momentum conservation.', r'$(cp_1,\vec p_1)+(mc^2,0)=(cp_2,\vec p_2)+(\sqrt{m^2c^4+p^2c^2},\vec p)$. Eliminate the electron: $p^2=p_1^2-2p_1p_2\cos\theta+p_2^2$ (momentum), and from the energy $(p_1-p_2+mc)^2=m^2c^2+p^2$. Together $2p_1p_2(1-\cos\theta)=2mc(p_1-p_2)$; divide by $p_1p_2$ and use $\lambda=h/p$.'),
    ('(iii) Limits.', r'The shift is at most $2h/mc$ with $\lambda_C=h/mc=2.42\times10^{-12}$ m. For $\lambda\gg\lambda_C$ (visible light, $10^{-7}$ m) the relative change is negligible: Thomson. Only hard X-rays and $\gamma$-rays show it.')],
   [r'classical solution oscillates at $\omega$', r'4-momentum conservation and eliminating the electron', r'$\Delta\lambda=\frac{h}{mc}(1-\cos\theta)$', r'$\lambda_C=2.4$ pm: X-rays/$\gamma$']),
 Q(2, 'Bohr atom', 'wave-mechanics-basics', ['qm-wm-L1', 'qm-hl-L1'],
   r'Bohr: $mv_nr_n=n\hbar$, $r_n=\frac{n^2\hbar^2}{me^2}$ (Gaussian units). (i) With $\lambda=h/p$ show $\lambda/r_n=2\pi/n$: the wave fits around the orbit. (ii) Show $v_n\ll c$. (iii) Show that the emitted wavelength (e.g. $n=\infty\to1$) is much larger than the Bohr radius.',
   [('(i) Standing wave.', r'$\frac{\lambda}{r_n}=\frac{h}{mv_nr_n}=\frac{2\pi\hbar}{n\hbar}=\frac{2\pi}n$: $n$ wavelengths fit on the circumference.'),
    ('(ii) Speed.', r'$v_n=\frac{n\hbar}{mr_n}=\frac{e^2}{n\hbar}\le v_1=\alpha c=2.19\times10^6$ m/s $\ll c$ ($\alpha\approx1/137$).'),
    ('(iii) Wavelength vs size.', r'$E_n=-13.6\ \mathrm{eV}/n^2$, $\lambda_{nm}=\frac{hc}{E_n-E_m}\ge\lambda_{\infty1}=\frac{hc}{13.6\ \mathrm{eV}}\approx91$ nm $\gg a_0=0.053$ nm: the atom is tiny compared with its light (dipole approximation).')],
   [r'$\lambda/r_n=2\pi/n$', r'$v_1=\alpha c\ll c$', r'$91$ nm vs $0.053$ nm']),
 Q(3, 'Galilei invariance of the Schrödinger equation', 'wave-mechanics-basics', ['qm-wm-L2'],
   r'If $\Psi(x,t)$ solves the free Schrödinger equation $i\hbar\partial_t\Psi=-\frac{\hbar^2}{2m}\partial_x^2\Psi$, show that $\Psi_u(x,t)=\Psi(x-ut,t)\exp\left[\frac{im}{\hbar}ux-\frac{im}{2\hbar}u^2t\right]$ is a solution for every constant $u$.',
   [('Time derivative.', r'$i\hbar\partial_t\Psi_u=\left[i\hbar\partial_t\Psi-i\hbar u\,\partial_x\Psi+\frac m2u^2\Psi\right]e^{imu(x-ut/2)/\hbar}$ (arguments $x-ut,t$), and $i\hbar\partial_t\Psi=-\frac{\hbar^2}{2m}\partial_x^2\Psi$.'),
    ('Space derivatives.', r'$-\frac{\hbar^2}{2m}\partial_x^2\Psi_u=\left[-\frac{\hbar^2}{2m}\partial_x^2\Psi-i\hbar u\,\partial_x\Psi+\frac m2u^2\Psi\right]e^{imu(x-ut/2)/\hbar}$: identical. The phase $e^{imux/\hbar}$ is the boost of the momentum by $mu$.')],
   [r'chain rule for $\Psi(x-ut,t)$', r'both sides give the same three terms', r'interpretation: momentum boost by $mu$']),
])

S(2, 'Ehrenfest, real energies, probability current', '2025-10-01', [
 Q(1, 'Ehrenfest’s theorem', 'wave-mechanics-basics', ['qm-wm-D3', 'qm-wm-L2', 'qm-fu-L4', 'qm-ho-b3'],
   r'Prove $m\frac{d^2}{dt^2}\langle x\rangle=-\langle V^\prime(x)\rangle$ for motion in a potential $V$. Hint: bring $\frac{d}{dt}\langle x\rangle$ into a form proportional to $\Psi\overleftrightarrow{\partial_x}\Psi^*$.',
   [(r'First derivative.', r'With the Schrödinger equation, $\frac{d}{dt}\langle x\rangle=\frac{i\hbar}{2m}\int x\,\partial_x(\Psi^*\partial_x\Psi-\Psi\partial_x\Psi^*)dx=-\frac{i\hbar}{2m}\int(\Psi^*\partial_x\Psi-\Psi\partial_x\Psi^*)dx=\frac{\langle p\rangle}{m}$ (integration by parts, no boundary terms).'),
    (r'Second derivative.', r'$\frac{d^2}{dt^2}\langle x\rangle=\frac1m\int\left[(H\Psi)^*\partial_x\Psi+\partial_x\Psi^*(H\Psi)\right]dx$; the kinetic terms cancel by parts, the potential terms give $\int\left[\Psi^*V\partial_x\Psi+\partial_x\Psi^*V\Psi\right]=-\int\Psi^*(\partial_xV)\Psi$.'),
    ('Result.', r'$m\frac{d^2}{dt^2}\langle x\rangle=-\langle\partial_xV\rangle$: Newton for averages. Not $-V^\prime(\langle x\rangle)$, except for at most quadratic $V$.')],
   [r'$d\langle x\rangle/dt=\langle p\rangle/m$ via the current', r'time derivatives replaced by $H$', r'integration by parts leaving $-\langle V^\prime\rangle$', r'difference to $V^\prime(\langle x\rangle)$']),
 Q(2, 'Reality of energy', 'formalism-and-uncertainty', ['qm-fu-D1', 'qm-fu-L1'],
   r'Show that the expectation value of the Hamiltonian of a non-relativistic particle is real, $\langle H\rangle=\langle H\rangle^*$.',
   [('Write both.', r'$\langle H\rangle=-\frac{\hbar^2}{2m}\int\Psi^*\Psi^{\prime\prime}+\langle V\rangle$, $\langle H\rangle^*=-\frac{\hbar^2}{2m}\int\Psi^{*\prime\prime}\Psi+\langle V\rangle$ ($V$ real).'),
    ('Difference.', r'$\int(\Psi^*\Psi^{\prime\prime}-\Psi^{*\prime\prime}\Psi)=\int(-\Psi^{*\prime}\Psi^\prime+\Psi^{*\prime}\Psi^\prime)=0$ by parts: $H$ is hermitian on normalisable states.')],
   [r'real potential', r'integration by parts twice', r'hermiticity as the reason']),
 Q(3, 'Probability current', 'tunneling-bridge', ['qm-tunnel-L1', 'qm-tunnel-D1', 'qm-wm-D2'],
   r'Show that $\Psi_k=\left(Ae^{ikx/\hbar}+Be^{-ikx/\hbar}\right)e^{-iE_kt/\hbar}$, $E_k=k^2/2m$, solves the free Schrödinger equation and that its current is $j=\frac km(|A|^2-|B|^2)$.',
   [('Solution.', r'Each $e^{\pm ikx/\hbar}e^{-iE_kt/\hbar}$ solves it ($i\hbar\cdot(-iE_k/\hbar)=\frac{k^2}{2m}$), the time factor is even in $k$, and the equation is linear.'),
    ('Current.', r'$j=\frac{\hbar}{2mi}(\Psi^*\partial_x\Psi-\Psi\partial_x\Psi^*)$: the cross terms $AB^*$ cancel, leaving $\frac km(|A|^2-|B|^2)$: right-movers minus left-movers, each with velocity $k/m$ ($k$ is the momentum here).')],
   [r'superposition of two plane waves', r'cross terms cancel in $j$', r'$j=\frac km(|A|^2-|B|^2)$']),
])

S(3, 'Gaussians and the box', '2025-10-08', [
 Q(1, 'Gaussian wave functions', 'wave-mechanics-basics', ['qm-wm-L3', 'qm-wm-D4', 'qm-wm-c2', 'lab-qm-wavepacket'],
   r'$\Psi(x)=Ae^{-\lambda x^2/2}$, $\lambda>0$. (i) Normalise. (ii) Sketch; find $V$ (with $V(0)=0$) for which $\Psi$ is a stationary state, and $E$. (iii) Compute $\Delta x$, $\Delta p$ and $\Delta x\Delta p$. (iv) How would you tune $\lambda$ to localise the particle, and why can $\Delta x=0$ not be reached?',
   [('(i) Normalisation.', r'$\int|A|^2e^{-\lambda x^2}dx=|A|^2\sqrt{\pi/\lambda}=1$: $A=(\lambda/\pi)^{1/4}$ (up to a phase).'),
    ('(ii) Potential.', r'$\Psi^{\prime\prime}=(\lambda^2x^2-\lambda)\Psi$, so $V=\frac{\hbar^2\lambda^2}{2m}x^2$ and $E=\frac{\hbar^2\lambda}{2m}$: the harmonic oscillator ground state ($\lambda=m\omega/\hbar$, $E=\hbar\omega/2$). Larger $\lambda$: narrower bell.'),
    ('(iii) Uncertainties.', r'$\langle x\rangle=\langle p\rangle=0$, $\langle x^2\rangle=\frac1{2\lambda}$ (differentiate $\int e^{-\lambda x^2}$ w.r.t. $\lambda$), $\langle p^2\rangle=\frac{\hbar^2\lambda}2$: $\Delta x\Delta p=\frac\hbar2$, the minimum.'),
    ('(iv) Localising.', r'Large $\lambda$ (steep trap) gives small $\Delta x$, but $\Delta p=\hbar\sqrt{\lambda/2}$ and $E=\hbar^2\lambda/2m$ diverge: $\Delta x\to0$ costs infinite energy.')],
   [r'$A=(\lambda/\pi)^{1/4}$', r'harmonic potential with $E=\hbar^2\lambda/2m$', r'$\Delta x\Delta p=\hbar/2$', r'localisation costs energy']),
 Q(2, 'Particle in a box I', 'wave-mechanics-basics', ['qm-wm-L4', 'qm-wm-b1'],
   r'(i) A particle in $[0,a]$ has $\Psi(x,0)=1/\sqrt a$. Probability of measuring $E_n=\frac{n^2\pi^2\hbar^2}{2ma^2}$? ($\psi_n=\sqrt{2/a}\sin\frac{n\pi x}a$.) (ii) Deduce $\sum_m\frac1{(2m-1)^2}=\frac{\pi^2}8$ and $\zeta(2)=\frac{\pi^2}6$.',
   [('(i) Overlap.', r'$p_n=\left|\int_0^a\sqrt{\frac2a}\sin\frac{n\pi x}{a}\frac{1}{\sqrt a}dx\right|^2=\frac{2}{n^2\pi^2}(1-(-1)^n)^2=\frac{8}{n^2\pi^2}$ for odd $n$, 0 for even $n$.'),
    ('(ii) Sums.', r'$\sum p_n=1\Rightarrow\sum_{\rm odd}\frac1{n^2}=\frac{\pi^2}8$. Then $\zeta(2)=\frac{\zeta(2)}4+\frac{\pi^2}8$, so $\zeta(2)=\frac{\pi^2}6$.')],
   [r'overlap integral and odd/even pattern', r'$p_n=8/(n\pi)^2$', r'completeness gives the sums']),
 Q(3, 'Particle in a box II', 'wave-mechanics-basics', ['qm-wm-L4', 'qm-wm-b2'],
   r'In the $n$-th eigenstate of the box $[0,a]$ show $\langle x\rangle=\frac a2$, $\langle(x-\langle x\rangle)^2\rangle=\frac{a^2}{12}\left(1-\frac{6}{n^2\pi^2}\right)$, and that the classical limit is approached as $n\to\infty$.',
   [('Mean.', r'$\langle x\rangle=\int_0^a\frac{x}{a}\left(1-\cos\frac{2\pi nx}a\right)dx=\frac a2$ (the cosine term integrates to 0 by parts).'),
    ('Variance.', r'$\langle x^2\rangle=\frac{a^2}3-\frac{a^2}{2\pi^2n^2}$ (two integrations by parts), so $(\Delta x)^2=\frac{a^2}{12}-\frac{a^2}{2\pi^2n^2}$.'),
    ('Classical limit.', r'A classical particle is uniform on $[0,a]$: $\langle x\rangle=a/2$, $(\Delta x)^2=a^2/12$, reached for $n\to\infty$ (correspondence principle).')],
   [r'$\langle x\rangle=a/2$', r'$\langle x^2\rangle$ by parts', r'uniform classical distribution as the limit']),
 Q(4, 'Particle in a box III: the sudden wall', 'wave-mechanics-basics', ['qm-wm-D5', 'qm-wm-c3', 'lab-qm-wavepacket'],
   r'A particle in the ground state of $[0,a]$; the wall at $a$ jumps suddenly to $2a$. Expand in the eigenfunctions of $[0,2a]$, give $\Psi(x,t)$, show that only $n=2$ and odd $n$ contribute ($E_n=\frac{n^2\pi^2\hbar^2}{8ma^2}$) and that the energy is unchanged with probability 1/2. Classical intuition?',
   [('Expansion.', r'$c_n=\frac{\sqrt2}{a}\int_0^a\sin\frac{\pi x}a\sin\frac{n\pi x}{2a}dx$; with $2\sin\sin=\cos-\cos$: $c_2=\frac1{\sqrt2}$, and for $n\ne2$: $c_n=\frac{\sin\pi(1-n/2)}{\sqrt2\pi(1-n/2)}-\frac{\sin\pi(1+n/2)}{\sqrt2\pi(1+n/2)}$, zero for even $n>2$.'),
    ('Time evolution and the probability.', r'$\Psi(x,t)=\sum c_n\psi_n(x)e^{-iE_nt/\hbar}$. $E_2$ of the new box equals the old ground energy: probability $|c_2|^2=\frac12$ (odd $n$: $P_n=\frac{32}{\pi^2(4-n^2)^2}$).'),
    ('Classical picture.', r'The particle bounces freely; moving a wall instantly (not touching it) does not change its kinetic energy. Quantum mechanically the mean energy is conserved too ($\langle H\rangle$ of the unchanged state), but individual outcomes spread.')],
   [r'limits of integration $0..a$', r'$c_2=1/\sqrt2$, even $n>2$ vanish', r'$P(E\ \mathrm{unchanged})=1/2$', r'classical expectation']),
])

S(4, 'Delta potential, wells, the deuteron', '2025-10-15', [
 Q(1, 'One-dimensional delta potential', 'tunneling-bridge', ['qm-tunnel-L2', 'qm-tunnel-D3'],
   r'$V=V\delta(x)$; ansatz $\psi=e^{ikx/\hbar}+Re^{-ikx/\hbar}$ ($x<0$), $Te^{ikx/\hbar}$ ($x>0$), $E=k^2/2m$. Find the matching conditions, $R$, $T$ and check $|R|^2+|T|^2=1$.',
   [('Jump condition.', r'Integrate from $-\epsilon$ to $\epsilon$: $\psi$ continuous, $\frac{\hbar^2}{2m}(\psi^\prime(0^+)-\psi^\prime(0^-))=V\psi(0)$.'),
    ('Solve.', r'$1+R=T$ and $\frac{\hbar^2}{2m}\frac{ik}{\hbar}(T-1+R)=VT$ give $R=\frac{-imV}{\hbar k+imV}$, $T=\frac{\hbar k}{\hbar k+imV}$.'),
    ('Conservation.', r'$|R|^2+|T|^2=\frac{m^2V^2+\hbar^2k^2}{\hbar^2k^2+m^2V^2}=1$. High energies transmit, the sign of $V$ does not matter for $|T|$.')],
   [r'derivative jumps by $\frac{2mV}{\hbar^2}\psi(0)$', r'$R$, $T$', r'$|R|^2+|T|^2=1$']),
 Q(2, 'Infinitely deep, infinitely narrow well', 'tunneling-bridge', ['qm-tunnel-D3', 'qm-tunnel-L4'],
   r'Square well $V=-V_0$ for $|x|<a$. Show that for $V_0\to\infty$, $a\to0$ with $V_0a$ fixed the ground-state energy stays finite and negative.',
   [('Even ansatz.', r'$\psi=b\cos kx$ inside, $e^{-\kappa|x|}$ outside, $k=\sqrt{2m(E+V_0)}/\hbar$, $\kappa=\sqrt{-2mE}/\hbar$; matching: $e^{-\kappa a}=b\cos ka$, $\kappa e^{-\kappa a}=bk\sin ka$.'),
    ('Limit.', r'$ka\to0$ (since $k\sim\sqrt{V_0}$, $a\sim1/V_0$): $b=1$, $\kappa=k^2a\to\frac{2mV_0a}{\hbar^2}$, so $E_0=-\frac{\hbar^2\kappa^2}{2m}=-\frac{2m(V_0a)^2}{\hbar^2}$, finite.'),
    ('Slicker.', r'The well becomes $-2V_0a\,\delta(x)$; with the jump condition of Q1, $\psi=e^{-\kappa|x|}$ gives the same $\kappa$. Exactly one bound state.')],
   [r'even ansatz and matching', r'limit $ka\to0$', r'$E_0=-2m(V_0a)^2/\hbar^2$', r'delta-function picture']),
 Q(3, 'General potentials', 'tunneling-bridge', ['qm-tunnel-D1', 'qm-tunnel-L1'],
   r'(i) For a stationary scattering state $\chi=e^{ikx}+Ae^{-ikx}$ ($x\ll0$), $Be^{ikx}$ ($x\gg0$) show that $j$ is independent of $x$ and $|A|^2+|B|^2=1$; interpret. (ii) Show $\langle T\rangle\ge0$ and that the lowest energy in any well lies above the bottom of the well.',
   [('(i) Constant current.', r'$\partial_xj=-\partial_t|\psi|^2=0$ for stationary states. Left: $j=\frac{\hbar k}m(1-|A|^2)$, right: $\frac{\hbar k}m|B|^2$: equal, so $|A|^2+|B|^2=1$: every particle is reflected or transmitted.'),
    ('(ii) Positive kinetic energy.', r'$\langle T\rangle=\frac{\hbar^2}{2m}\int|\partial_x\psi|^2\ge0$ (by parts), strictly $>0$ for a normalisable state. Hence $\langle H\rangle\ge V_{\min}+\langle T\rangle>V_{\min}$.')],
   [r'continuity equation $\Rightarrow$ $x$-independent $j$', r'$|A|^2+|B|^2=1$ with interpretation', r'$\langle T\rangle=\frac{\hbar^2}{2m}\int|\psi^\prime|^2>0$']),
 Q(4, 'The deuteron', 'tunneling-bridge', ['qm-tunnel-L4', 'qm-tunnel-D2'],
   r'3D square well $V=-V$ for $r<a$, 0 outside. Find the spherically symmetric bound states (hint: $\chi=r\psi$). Is there always a bound state?',
   [('Radial equation.', r'$-\frac{\hbar^2}{2m}\chi^{\prime\prime}+V(r)\chi=E\chi$ with $\chi(0)=0$: the 1D well, but only odd solutions.'),
    ('Matching.', r'$\chi=\sin kr$ inside, $e^{-\kappa r}$ outside; with $\xi=ka$, $\eta=\kappa a$: $\eta=-\xi\cot\xi$ and $\xi^2+\eta^2=\frac{2ma^2V}{\hbar^2}$.'),
    ('Existence.', r'$-\xi\cot\xi<0$ for $\xi<\pi/2$, so a solution needs $\frac{2ma^2V}{\hbar^2}>\frac{\pi^2}4$: unlike 1D, a 3D well needs a minimum depth $V>\frac{\pi^2\hbar^2}{8ma^2}$. The deuteron is barely bound.')],
   [r'$\chi=r\psi$, $\chi(0)=0$', r'odd solutions, $\eta=-\xi\cot\xi$', r'threshold $2ma^2V/\hbar^2>\pi^2/4$']),
])

S(5, 'Transfer matrices, rays, commutators', '2025-10-22', [
 Q(1, 'Transfer matrix method', 'tunneling-bridge', ['qm-tunnel-L3', 'qm-tunnel-c1', 'qm-tunnel-e1', 'qm-tunnel-p1'],
   r'Piecewise constant potentials. (i) Step $V_L\to V_R$ at 0: find $M$ with $\binom{A_L}{B_L}=M\binom{A_R}{B_R}$. (ii) Propagation matrix $N$ over a region $[x_1,x_2]$. (iii) Chain them for a general potential. (iv) Square well $-V$ for $|x|<\ell/2$: $M_{\rm full}$; when is $N=I$, and what does it mean? (v) Barrier $V$, $0<E<V$, $B_R=0$, $A_L=1$: show $|B_L|^2+|A_R|^2=1$ and compute $|A_R|^2$.',
   [('(i) Step.', r'Continuity of $\psi,\psi^\prime$: $A_L+B_L=A_R+B_R$, $k(A_L-B_L)=q(A_R-B_R)$, so $M=\frac12\begin{pmatrix}1+\eta&1-\eta\\1-\eta&1+\eta\end{pmatrix}$, $\eta=q/k$.'),
    ('(ii)-(iii) Propagation and chain.', r'$N=\mathrm{diag}(e^{-ik\ell},e^{ik\ell})$, $\ell=x_2-x_1$. In general $\binom{A_L}{B_L}=M_{n+1,n}N_nM_{n,n-1}\cdots N_1M_{1,0}\binom{A_R}{B_R}$.'),
    ('(iv) Well.', r'$M_{\rm full}=M^{-1}NM$ with $q=\sqrt{2m(E+V)}/\hbar$. $N=I$ iff $q\ell=2\pi n$: the wave fits into the well, $M_{\rm full}=I$, perfect transmission (resonance).'),
    ('(v) Barrier.', r'$q=i\kappa$, $\alpha=k/\kappa$: $1=A_R(\cosh\kappa\ell+\frac i2\frac{1-\alpha^2}{\alpha}\sinh\kappa\ell)$, $B_L=A_R\frac i2\frac{1+\alpha^2}\alpha\sinh\kappa\ell$; squaring gives $|A_R|^2+|B_L|^2=1$ and $T=|A_R|^2=\left[1+\frac{V^2}{4E(V-E)}\sinh^2\kappa\ell\right]^{-1}$. Classically $T=0$.')],
   [r'step matrix $M(\eta)$', r'propagation $N$ and the chain', r'resonance $q\ell=2\pi n$', r'barrier $T$ with $\sinh^2\kappa\ell$']),
 Q(2, r'Rays in $\mathbb C^2$', 'formalism-and-uncertainty', ['qm-fu-L1', 'qm-am-L2'],
   r'$\mathcal H=\mathbb C^2$ with basis $|1\rangle,|2\rangle$. (i) Are $|\Psi\rangle$ and $\mu|\Psi\rangle$ physically different? (ii) Show almost every state is $|1\rangle+z|2\rangle$; which are not, and do different $z$ give different states? (iii) What state is $|z|\to\infty$? (iv) What geometric object is the space of states?',
   [('(i) Rays.', r'All probabilities $\frac{|\langle\Phi|\Psi\rangle|^2}{\langle\Phi|\Phi\rangle\langle\Psi|\Psi\rangle}$ are unchanged by $\mu$: physical states are rays.'),
    ('(ii)-(iii) Coordinates.', r'$a|1\rangle+b|2\rangle\sim|1\rangle+\frac ba|2\rangle$ if $a\ne0$; distinct $z$ are distinct rays. Only $|2\rangle$ is missing, and it is the limit $|z|\to\infty$.'),
    ('(iv) The sphere.', r'$\mathbb C\cup\{\infty\}$ is the Riemann sphere $S^2$ (stereographic projection): the Bloch sphere of a spin-$\frac12$/qubit, $\mathbb{CP}^1\cong S^2$.')],
   [r'states are rays', r'$z$ as a coordinate, $|2\rangle$ missing', r'Riemann/Bloch sphere']),
 Q(3, 'Commutators', 'formalism-and-uncertainty', ['qm-fu-D1', 'qm-fu-L3'],
   r'(i) Show $(iAB)^\dagger=-iB^\dagger A^\dagger$ and that $i[A,B]$ is self-adjoint for self-adjoint $A,B$. (ii) With $[x,p]=i\hbar$ show $e^{iap/\hbar}xe^{-iap/\hbar}=x+a$. (iii) Deduce $e^{iap/\hbar}f(x)e^{-iap/\hbar}=f(x+a)$ and Weyl’s relation $e^{iap/\hbar}e^{ibx/\hbar}=e^{iba/\hbar}e^{ibx/\hbar}e^{iap/\hbar}$.',
   [('(i) Adjoint.', r'$\langle f|iABg\rangle=\langle-iB^\dagger A^\dagger f|g\rangle$ for all $f,g$. Then $(i[A,B])^\dagger=-iBA+iAB=i[A,B]$.'),
    ('(ii) Translation.', r'$p^nx=xp^n-ni\hbar p^{n-1}$, so $e^{iap/\hbar}x=(x+a)e^{iap/\hbar}$; multiply by $e^{-iap/\hbar}$ from the right ($e^{iap/\hbar}e^{-iap/\hbar}=I$).'),
    ('(iii) Functions and Weyl.', r'Conjugation is multiplicative, so $x^n\to(x+a)^n$ and $f(x)\to f(x+a)$. With $f=e^{ibx/\hbar}$: $e^{iap/\hbar}e^{ibx/\hbar}=e^{ib(x+a)/\hbar}e^{iap/\hbar}$, the Weyl form.')],
   [r'$(iAB)^\dagger=-iB^\dagger A^\dagger$', r'$p^nx=xp^n-ni\hbar p^{n-1}$', r'translation $f(x)\to f(x+a)$', r'Weyl relation']),
])

S(6, 'Momentum space and uncertainty', '2025-10-29', [
 Q(1, 'Delta well in momentum space', 'tunneling-bridge', ['qm-tunnel-D3', 'qm-tunnel-L2'],
   r'$V=-\alpha\delta(x)$. (i) Bound states in position space. (ii) Show the momentum-space equation $\frac{p^2}{2m}\tilde\psi+\frac1{\sqrt{2\pi\hbar}}\int\tilde V(p-p^\prime)\tilde\psi(p^\prime)dp^\prime=E\tilde\psi$. (iii) Compute $\tilde V$ and solve in terms of $C=\int\tilde\psi\,dp$. (iv) Get the allowed $E$. (v) Compare with the Fourier transform of (i). (vi) What goes wrong for $E>0$, or for a barrier?',
   [('(i) Position space.', r'$\psi=Ae^{-\kappa|x|}$, jump $\frac{\hbar^2}{2m}(\psi^\prime(0^+)-\psi^\prime(0^-))=-\alpha\psi(0)$ gives $\kappa=\frac{m\alpha}{\hbar^2}$, one bound state $E=-\frac{m\alpha^2}{2\hbar^2}$.'),
    ('(ii)-(iii) Momentum space.', r'Fourier transforming, $V\psi$ becomes a convolution; $\tilde V=-\frac{\alpha}{\sqrt{2\pi\hbar}}$ is constant, so the integral term is $-\frac{\alpha C}{2\pi\hbar}$ and $\left(\frac{p^2}{2m}-E\right)\tilde\psi=\frac{\alpha C}{2\pi\hbar}$: $\tilde\psi(p)=\frac{\alpha C}{2\pi\hbar}\,\frac{1}{p^2/2m-E}$, with $C=\sqrt{2\pi\hbar}\,\psi(0)$.'),
    ('(iv)-(v) Consistency.', r'Integrating both sides: $C=\frac{m\alpha C}{\hbar\sqrt{-2mE}}$, so $\hbar\sqrt{-2mE}=m\alpha$: the same $E$. The transform of $e^{-\kappa|x|}$ is a Lorentzian $\propto\frac{2\kappa}{\kappa^2+p^2/\hbar^2}$: the same function.'),
    ('(vi) Failures.', r'$E>0$: poles at $p=\pm\sqrt{2mE}$, $C$ diverges (scattering states are not normalisable). Barrier $+\alpha^\prime\delta$: $-m\alpha^\prime=\hbar\sqrt{-2mE}>0$ is impossible: no bound state.')],
   [r'$E=-m\alpha^2/2\hbar^2$ from the jump', r'convolution and constant $\tilde V$', r'Lorentzian $\tilde\psi$ and the self-consistency integral', r'why $E>0$ and barriers fail']),
 Q(2, 'Uncertainty relation in a box', 'formalism-and-uncertainty', ['qm-fu-L3', 'qm-fu-D2', 'qm-wm-L4'],
   r'For the $n$-th eigenstate of the box $[0,a]$ ($\langle x\rangle=a/2$, $(\Delta x)^2=\frac{a^2}{12}(1-\frac6{n^2\pi^2})$, sheet III) compute $\langle p\rangle$, $\Delta p$ and check $\Delta x\Delta p\ge\hbar/2$.',
   [('Momentum.', r'$\langle p\rangle=0$ (the integrand $\sin\cos$ is odd about $a/2$), $\langle p^2\rangle=\left(\frac{n\pi\hbar}a\right)^2$ (also $=2mE_n$), so $\Delta p=\frac{n\pi\hbar}a$.'),
    ('Product.', r'$\Delta x\Delta p=\frac\hbar2\sqrt{\frac{n^2\pi^2}3-2}\ge\frac\hbar2\times1.13$ for $n=1$, growing with $n$: Heisenberg holds, not saturated.')],
   [r'$\langle p\rangle=0$ by symmetry', r'$\Delta p=n\pi\hbar/a$', r'$\frac\hbar2\sqrt{n^2\pi^2/3-2}$']),
 Q(3, 'Uncertainty relation and energy', 'harmonic-oscillator-elevator', ['qm-ho-D4', 'qm-fu-D4'],
   r'$V=\frac12kx^2$. Express $\langle E\rangle$ through $\langle x\rangle,\langle p\rangle,\Delta x,\Delta p$, and use $\Delta x\Delta p\ge\hbar/2$ to show $\langle E\rangle\ge\frac\hbar2\sqrt{k/m}$.',
   [('Energy.', r'$\langle E\rangle=\frac{(\Delta p)^2+\langle p\rangle^2}{2m}+\frac k2\left((\Delta x)^2+\langle x\rangle^2\right)\ge\frac{(\Delta p)^2}{2m}+\frac k2(\Delta x)^2$.'),
    ('Bound.', r'Complete the square: $\ge\sqrt{k/m}\,\Delta x\Delta p\ge\frac\hbar2\sqrt{k/m}=\frac{\hbar\omega}2$ (or minimise $\frac{\mu}{2m}+\frac{k\hbar^2}{8\mu}$ over $\mu=(\Delta p)^2$). The zero-point energy is forced by uncertainty, and it is exactly the true ground state.')],
   [r'expectation values split into mean$^2$ + variance', r'AM-GM / completing the square', r'$\langle E\rangle\ge\hbar\omega/2$']),
])
